import React from 'react';
import './Hero.css';

export const Hero = () => {
  return (
    <section className="hero-section">

      {/* Layer 0 — Sky background */}
      <img
        src={process.env.PUBLIC_URL + '/bg%20hero.webp'}
        alt="Hero Background"
        className="hero-bg"
        aria-hidden="true"
      />

      {/* Layer 2 — Text, CTA & Dashboard */}
      <div className="nl-hero-content">
        <h1 className="nl-hero-heading">
          The intelligent travel companion<br />for every journey you take.
        </h1>
        <p className="nl-hero-subtitle">
          Your journey, our priority. Powered by AI, tailored for you.
        </p>
        <button id="nl-try-beta" className="nl-btn-hero-white">
          Join the Beta
        </button>

        <div className="hero-dashboard-wrapper">
          <div className="hero-dashboard-inner">
            <img
              src={process.env.PUBLIC_URL + '/hero%20bg%20new.webp'}
              alt="Dishastra app dashboard"
              className="hero-dashboard"
            />
          </div>
        </div>
      </div>

      {/* Layer 4 — Hills foreground */}
      <div className="hero-hills-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/image.webp'}
          alt="Landscape"
          className="hero-hills"
          aria-hidden="true"
        />
        <div className="hero-hills-overlay"></div>
      </div>

    </section>
  );
};
